import java.util.HashMap;
import java.util.Map;
import java.util.function.BiFunction;
import net.minecraft.core.BlockPos;
import net.minecraft.core.Direction;
import net.minecraft.world.level.Level;
import net.minecraft.world.level.block.entity.BlockEntity;
import net.minecraft.world.level.block.entity.BlockEntityType;
import org.antarcticgardens.esl.ESL;
import org.antarcticgardens.esl.energy.EnergyStorage;
import org.jetbrains.annotations.Nullable;

public abstract class BlockEnergyStorageManager {
    private final Map<BlockEntityType<? extends BlockEntity>, BiFunction<BlockEntity, Direction, EnergyStorage>> blockEntityProviders = new HashMap<BlockEntityType<? extends BlockEntity>, BiFunction<BlockEntity, Direction, EnergyStorage>>();

    public <T extends BlockEntity> void registerForBlockEntity(BiFunction<T, Direction, EnergyStorage> provider, BlockEntityType<T> blockEntityType) {
        if (this.blockEntityProviders.containsKey(blockEntityType)) {
            ESL.LOGGER.trace("Duplicate energy storage registration for " + String.valueOf(blockEntityType));
            return;
        }
        this.blockEntityProviders.put(blockEntityType, provider);
        this.platformRegisterForBlockEntity(provider, blockEntityType);
    }

    public boolean isBlockEntityRegisteredInESL(BlockEntityType<?> blockEntityType) {
        return this.blockEntityProviders.containsKey(blockEntityType);
    }

